// Merge the extractions of all sources linked to one project into one record. Rules, not a model: lists are united,
// every row keeps the source it came from (S<id>), and the strongest stage / evidence is taken.
const rows = $input.all().map(i => i.json).filter(r => r.project_id);
if (!rows.length) return [];
const P = rows[0];
const STAGE = ['idea', 'pilot', 'scaled'];
const EVID = ['none', 'anecdotal', 'pilot_report', 'observational', 'quasi_experimental', 'rct'];
const uniq = (a) => [...new Set(a.filter(x => x !== undefined && x !== null && String(x).trim() !== '').map(x => String(x).trim()))];
const tag = (sid) => 'S' + sid;
const live = rows.filter(r => r.fields && r.fields.is_ai4sg !== false);
const srcs = rows.map(r => {
  const f = r.fields || {}, src = f.source || {};
  return { sid: Number(r.source_id), title: src.title_en || r.title_en || r.title || r.url, title_original: src.title_original || r.title || '',
    url: r.url, doi: r.doi || '', type: r.source_type || '', published: src.published || '', publisher: src.publisher || '',
    language: src.language || r.language || '', country: r.country || '', text_level: r.text_level || (Number(r.text_chars) >= 3000 ? 'full' : Number(r.text_chars) > 0 ? 'abstract' : 'none'),
    text_chars: Number(r.text_chars) || 0, extracted: !!r.extraction_id, ai4sg: f.is_ai4sg !== false && !!r.fields,
    evidence: (f.evidence_strength || {}).type || 'none', evidence_rationale: (f.evidence_strength || {}).rationale || '',
    score: r.relevance_score, flags: r.flags || [], headline: f.headline || '', summary: src.summary_en || '',
    overall: (f.interpretation || {}).overall || '', credibility: (f.interpretation || {}).credibility || '',
    link_method: r.method || '', link_reason: r.reason || '' };
}).sort((a, b) => (EVID.indexOf(b.evidence) - EVID.indexOf(a.evidence)) || ((b.score || 0) - (a.score || 0)) || (a.sid - b.sid));
const F = (r) => r.fields || {};
const all = (get) => live.flatMap(r => { const v = get(F(r), r); return (Array.isArray(v) ? v : [v]).filter(x => x !== undefined && x !== null && x !== '').map(x => ({ v: x, sid: Number(r.source_id) })); });
// places: one entry per place, with the sources naming it
const places = [];
all(f => (f.location || {}).places || []).forEach(({ v, sid }) => {
  const k = `${String(v.name || '').toLowerCase()}|${v.level || ''}`;
  const e = places.find(x => x.k === k);
  if (e) { if (!e.sids.includes(sid)) e.sids.push(sid); } else places.push({ ...v, k, sids: [sid] });
});
const SCOPE = ['site', 'city', 'district', 'region', 'multi_region', 'national'];
const scopes = all(f => (f.location || {}).scope).map(x => x.v).filter(x => SCOPE.includes(x));
const stages = all(f => (f.project || {}).deployment_stage).map(x => ({ stage: x.v, sid: x.sid }));
const bestStage = stages.map(x => x.stage).filter(x => STAGE.includes(x)).sort((a, b) => STAGE.indexOf(b) - STAGE.indexOf(a))[0]
  || (stages.some(x => x.stage === 'discontinued') ? 'discontinued' : 'unknown');
const evid = srcs.filter(x => x.ai4sg).map(x => ({ type: x.evidence, sid: x.sid, rationale: x.evidence_rationale }));
const best = evid.slice().sort((a, b) => EVID.indexOf(b.type) - EVID.indexOf(a.type))[0] || { type: 'none' };
const tl = live.map(r => ({ ...(F(r).timeline || {}), sid: Number(r.source_id) })).filter(t => t.start_date || t.end_date || (t.status && t.status !== 'unknown'));
const dates = (k) => tl.map(t => t[k]).filter(Boolean).sort();
const latest = tl.slice().sort((a, b) => String(b.end_date || b.start_date || '').localeCompare(String(a.end_date || a.start_date || '')))[0] || {};
const dfs = {};
all(f => f.domain_fields || []).forEach(({ v, sid }) => { if (!v.field) return; (dfs[v.field] ||= []);
  if (v.value && !dfs[v.field].some(x => String(x.value).toLowerCase() === String(v.value).toLowerCase())) dfs[v.field].push({ value: v.value, sid, verified: v.verified });
  else if (v.value) { const e = dfs[v.field].find(x => String(x.value).toLowerCase() === String(v.value).toLowerCase()); e.sids = uniq([...(e.sids || [e.sid]), sid]); } });
const flags = {};
rows.forEach(r => (r.flags || []).forEach(fl => { flags[fl] = (flags[fl] || 0) + 1; }));
const scores = srcs.filter(x => x.ai4sg && x.score != null).map(x => Number(x.score));
const merged = {
  version: 1, built_at: new Date().toISOString(), source_ids: rows.map(r => Number(r.source_id)).sort((a, b) => a - b),
  n_sources: rows.length, n_analysed: live.length,
  names: uniq([P.name, ...(P.aliases || []), ...all(f => (f.project || {}).name).map(x => x.v)]),
  orgs: uniq(all(f => (f.project || {}).implementing_org).map(x => x.v)),
  partners: uniq(all(f => (f.project || {}).partners || []).map(x => x.v)), funders: uniq(all(f => (f.project || {}).funders || []).map(x => x.v)),
  countries: uniq([...all(f => (f.project || {}).countries || []).map(x => x.v), ...rows.map(r => r.country)]),
  domains: uniq(all(f => (f.project || {}).domain).map(x => x.v)), beneficiaries: uniq(all(f => (f.project || {}).target_beneficiaries).map(x => x.v)),
  government_roles: uniq(all(f => (f.project || {}).government_role).map(x => x.v).filter(x => x !== 'unknown')),
  stage: bestStage, stages, places: places.map(({ k, ...x }) => x), scope: scopes.sort((a, b) => SCOPE.indexOf(b) - SCOPE.indexOf(a))[0] || '',
  products: uniq(all(f => String((f.technology || {}).model_or_product || '').split(/\s*;\s*/)).map(x => x.v)),
  tech_categories: uniq(all(f => (f.technology || {}).category).map(x => x.v).filter(x => x !== 'unspecified')),
  tech: all(f => (f.technology || {}).specific).map(x => ({ text: x.v, sid: x.sid })),
  timeline: { start: dates('start_date')[0] || '', end: dates('end_date').slice(-1)[0] || '', status: latest.status || '',
              per_source: tl.map(t => ({ sid: t.sid, start: t.start_date || '', end: t.end_date || '', status: t.status || '', as_written: t.as_written || '' })) },
  use: { problems: all(f => (f.use || {}).problem).map(x => ({ text: x.v, sid: x.sid })), users: uniq(all(f => (f.use || {}).primary_user).map(x => x.v)),
         ai_roles: uniq(all(f => (f.use || {}).ai_role).map(x => x.v).filter(x => x !== 'unknown')),
         human_roles: all(f => (f.use || {}).human_role).map(x => ({ text: x.v, sid: x.sid })), channels: uniq(all(f => (f.use || {}).channel).map(x => x.v)) },
  domain_fields: Object.entries(dfs).map(([field, values]) => ({ field, values })),
  reach: live.map(r => ({ ...(F(r).reach || {}), sid: Number(r.source_id) })).filter(x => x.number != null && x.number !== '')
    .map(({ evidence_refs, ...x }) => x).sort((a, b) => (Number(b.number) || 0) - (Number(a.number) || 0)),
  cost: live.map(r => ({ ...(F(r).cost || {}), sid: Number(r.source_id) })).filter(c => c.stated || (c.breakdown || []).length)
    .map(({ evidence_refs, ...c }) => c),
  benefits: live.map(r => ({ ...(F(r).benefit || {}), sid: Number(r.source_id) })).filter(b => b.stated).map(({ evidence_refs, ...b }) => b),
  outcomes: live.flatMap(r => (F(r).outcomes || []).filter(o => o && (o.name || o.domain)).map(o => ({ ...o, sid: Number(r.source_id) }))),
  requirements: all(f => (f.implementation || {}).requirements || []).map(x => ({ text: x.v, sid: x.sid })),
  barriers: all(f => (f.implementation || {}).barriers || []).map(x => ({ text: x.v, sid: x.sid })),
  facilitators: all(f => (f.implementation || {}).facilitators || []).map(x => ({ text: x.v, sid: x.sid })),
  gaps: all(f => (f.interpretation || {}).gaps || []).map(x => ({ text: x.v, sid: x.sid })),
  evidence_best: best, evidence: evid, score_best: scores.length ? Math.max(...scores) : null, flags, sources: srcs,
};
// the project summary is written by the model only when several sources need reconciling
const many = live.length > 1;
const one = srcs.find(x => x.ai4sg) || srcs[0] || {};
const facts = JSON.stringify({ names: merged.names, orgs: merged.orgs, countries: merged.countries, places: merged.places.map(x => x.name),
  stage: merged.stage, products: merged.products, timeline: merged.timeline, reach: merged.reach.slice(0, 6), cost: merged.cost.slice(0, 4),
  outcomes: merged.outcomes.slice(0, 40).map(o => ({ S: o.sid, domain: o.domain, name: o.name, value: o.value, unit: o.unit, comparison: o.comparison, timing: o.timing, data: o.data_source })),
  evidence: merged.evidence });
const perSource = srcs.filter(x => x.ai4sg).map(x => `[S${x.sid}] ${x.title} (${x.type}${x.published ? ', ' + x.published : ''}; evidence: ${x.evidence}; text: ${x.text_level})\n` +
  `Headline: ${x.headline}\nSummary: ${x.summary}\nInterpretation: ${x.overall}\nCredibility: ${x.credibility}`).join('\n\n');
const prompt = `## Project summary for the experts' audit\nSeveral sources describe the same AI-for-social-good deployment (project). The experts ` +
  `review each source; this summary shows them the deployment as a whole. Write the project-level reading from the sources below; refer to sources as [S12]. Do not add facts the sources do not give.\n\n` +
  `Return:\n- name: a short name for the deployment, "Tool — place/phase" (not one study), e.g. "qXR chest X-ray triage — Dhaka TB screening centres"\n` +
  `- summary: 3-5 English sentences: who runs what AI for whom, where, since when, and how far it got (pilot, scaled, discontinued)\n` +
  `- evidence: 2-4 sentences: what the sources together show about benefits and costs, and how strong that evidence is\n` +
  `- agreements_conflicts: list of short points where sources agree or disagree (figures, dates, stage), each citing the sources\n` +
  `- gaps: list of what is still unknown about the project\n\n### Merged facts\n${facts.slice(0, 20000)}\n\n### Sources\n${perSource.slice(0, 30000)}`;
const fallback = { name: P.name, summary: [one.headline, one.summary].filter(Boolean).join(' '), evidence: one.overall || '',
  agreements_conflicts: [], gaps: merged.gaps.map(g => g.text).slice(0, 8), by: 'single source' };
return [{ json: { project_id: P.project_id, merged, many, prompt, fallback,
  org: merged.orgs[0] || '', countries: merged.countries } }];

// the model's summary when several sources were reconciled; otherwise the single source's own reading
const m = $('Merge Sources').first().json;
let llm = null; try { llm = $('Write Project Summary').first().json.output || null; } catch (e) {}
const merged = { ...m.merged, llm: llm ? { ...llm, by: 'GPT-6 Luna, from ' + m.merged.n_analysed + ' sources' } : m.fallback };
return [{ json: { project_id: m.project_id, synthesis: merged, org: m.org, countries: m.countries } }];
